package org.sportssimulation.virtualrun;
public final class CoordinateTransformTest {public static void main(String[] args){double[][] places={{39.9042,116.4074},{31.2304,121.4737},{23.1291,113.2644},{30.5728,104.0668},{0,0},{40,-73}};for(double[] p:places){double[] g=CoordinateTransform.toGcj(p[0],p[1]),w=CoordinateTransform.toWgs(g[0],g[1]);if(Math.abs(w[0]-p[0])>1e-7||Math.abs(w[1]-p[1])>1e-7)throw new AssertionError("round trip");}double[] g=CoordinateTransform.toGcj(39.9042,116.4074);if(Math.abs(g[0]-39.9042)<.0001||Math.abs(g[1]-116.4074)<.0001)throw new AssertionError("China transform missing");System.out.println("PASS 7 coordinate conversion checks");}}
